# Cotizador: vincular el taller con hetnacnc.com (una sola cuenta) y
# /cotizador/?planes=1 abre la pantalla de planes (para los correos).
# Uso: python3 aplicar_vincular.py   (dentro de la carpeta del repo Cotizador)
import sys
def cambia(p, viejo, nuevo):
    s = open(p, encoding="utf-8").read()
    if s.count(viejo) != 1: sys.exit("No encontre el texto a cambiar en " + p)
    open(p, "w", encoding="utf-8").write(s.replace(viejo, nuevo))
