cambia('lib/screens/config_screen.dart', '          }),\n      ]));\n  }\n\n', '          }),\n      ]));\n  }\n\n  // Una sola cuenta: con el código de hetnacnc.com → Mi cuenta, la tienda\n  // entra a esta app sin pedir la contraseña y el plan cuenta también allá.\n  Future<void> _vincular() async {\n    final codigo = _codigoVinculo.text.replaceAll(RegExp(r\'\\D\'), \'\');\n    final token = AuthService.sesion?.accessToken;\n    if (codigo.length != 6 || token == null) {\n      _aviso(tr(\'Escribe los 6 dígitos del código.\'));\n      return;\n    }\n    setState(() => _vinculando = true);\n    try {\n      final r = await SuscripcionApi.vincular(token, codigo);\n      _codigoVinculo.clear();\n      _aviso(trf(\'Listo: {0} quedó vinculado con tu cuenta de hetnacnc.com.\', [r[\'taller\'] ?? tr(\'tu taller\')]));\n    } catch (e) {\n      _aviso(e.toString());\n    } finally {\n      if (mounted) setState(() => _vinculando = false);\n    }\n  }\n\n  void _aviso(String m) {\n    if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(m)));\n  }\n\n  Widget _seccionVincular() {\n    if (!AuthService.esAdmin) {\n      return Text(tr(\'Solo el administrador del taller puede vincularlo con hetnacnc.com.\'),\n        style: const TextStyle(fontSize: 12, color: AppColors.textoSecundario));\n    }\n    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [\n      Text(tr(\'Usa una sola cuenta: en hetnacnc.com entra a Mi cuenta → Cotizador para talleres → "Vincular mi taller" y escribe aquí el código. Después el botón Cotizador de la tienda entra sin contraseña y tu plan también cuenta en la tienda.\'),\n        style: const TextStyle(fontSize: 12, color: AppColors.textoSecundario)),\n      const SizedBox(height: 8),\n      Row(children: [\n        Expanded(child: TextField(\n          controller: _codigoVinculo,\n          keyboardType: TextInputType.number,\n          maxLength: 6,\n          decoration: InputDecoration(labelText: tr(\'Código de 6 dígitos\'), counterText: \'\',\n            border: const OutlineInputBorder(), isDense: true))),\n        const SizedBox(width: 8),\n        ElevatedButton(\n          onPressed: _vinculando ? null : _vincular,\n          child: _vinculando\n            ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2))\n            : Text(tr(\'Vincular\'))),\n      ]),\n    ]);\n  }\n\n')
cambia('lib/screens/home_screen.dart', '  @override\n  void initState() { super.initState(); _cargarAlertas(); }\n\n', '  @override\n  void initState() { super.initState(); _cargarAlertas(); _abrirPlanesSiLoPide(); }\n\n  // Los correos de "elige tu plan" abren hetnacnc.com/cotizador/?planes=1: al\n  // entrar se abre la pantalla de planes (una vez por sesión). En Android/iOS\n  // Uri.base no trae parámetros, así que ahí no pasa nada.\n  static bool _planesMostrados = false;\n  void _abrirPlanesSiLoPide() {\n    if (_planesMostrados || Uri.base.queryParameters[\'planes\'] != \'1\') return;\n    _planesMostrados = true;\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (mounted) Navigator.push(context, MaterialPageRoute(builder: (_) => const PremiumScreen()));\n    });\n  }\n\n')
cambia('lib/services/hetna_api.dart', "  static Future<Map<String, dynamic>> cancelar(String token) => _post('$_ruta/cancelar', token);\n}\n", "  static Future<Map<String, dynamic>> cancelar(String token) => _post('$_ruta/cancelar', token);\n\n  /// Vincula este taller con la cuenta de hetnacnc.com con el código de 6\n  /// dígitos que se saca en hetnacnc.com → Mi cuenta. Devuelve { ok, taller }.\n  static Future<Map<String, dynamic>> vincular(String token, String codigo) =>\n    _post('$_ruta/vincular', token, {'codigo': codigo});\n}\n")
